"import com.intellij.psi.*
import com.intellij.psi.util.PsiTreeUtil
import com.intellij.psi.util.InheritanceUtil
import com.intellij.codeInsight.AnnotationUtil
import com.siyeh.ig.psiutils.VariableAccessUtils

def MBC = "com.google.errorprone.annotations.MustBeClosed"
def call = __context__
if (!(call instanceof PsiCallExpression)) return false
def method = call.resolveMethod()
if (method == null) return false
if (call instanceof PsiMethodCallExpression && call.methodExpression.text in ["this", "super"]) return false
if (!AnnotationUtil.isAnnotated(method, MBC, 0) && !(method.containingClass?.qualifiedName == "java.lang.foreign.Arena" && method.name in ["ofConfined", "ofShared"])) return false

// Error Prone scans only method bodies (including lambdas and local/anonymous classes within them)
if (PsiTreeUtil.getParentOfType(call, PsiMethod) == null) return false

def mockito = { PsiMethod m -> m != null && m.containingClass?.qualifiedName == "org.mockito.Mockito" }
def argList = call.parent
if (argList instanceof PsiExpressionList && argList.parent instanceof PsiMethodCallExpression && mockito(argList.parent.resolveMethod()) && argList.parent.resolveMethod().name == "when") return false
if (call instanceof PsiMethodCallExpression) {
    def q = call.methodExpression.qualifierExpression
    if (q instanceof PsiMethodCallExpression && mockito(q.resolveMethod())) return false
}

def isMbc = { PsiModifierListOwner o -> o != null && AnnotationUtil.isAnnotated(o, MBC, 0) }
def lambdaOk = { PsiLambdaExpression l -> isMbc(LambdaUtil.getFunctionalInterfaceMethod(l.functionalInterfaceType)) }
def isA = { PsiClass c, String fqn -> c != null && InheritanceUtil.isInheritor(c, fqn) }
def DECORATORS = [
    "java.io.InputStream": ["java.io.FilterInputStream", "java.io.InputStreamReader"],
    "java.io.OutputStream": ["java.io.FilterOutputStream", "java.io.OutputStreamWriter"],
    "java.io.Reader": ["java.io.Reader"],
    "java.io.Writer": ["java.io.Writer"]
]
def closedInFinally = { PsiLocalVariable v ->
    def decl = v.parent
    if (!(decl instanceof PsiDeclarationStatement) || !(decl.parent instanceof PsiCodeBlock)) return false
    if (!v.hasModifierProperty(PsiModifier.FINAL) && VariableAccessUtils.variableIsAssigned(v, decl.parent)) return false
    def next = PsiTreeUtil.getNextSiblingOfType(decl, PsiStatement)
    if (!(next instanceof PsiTryStatement) || next.finallyBlock == null) return false
    return PsiTreeUtil.findChildrenOfType(next.finallyBlock, PsiMethodCallExpression).any { c ->
        def q = c.methodExpression.qualifierExpression
        c.methodExpression.referenceName == "close" && q instanceof PsiReferenceExpression && q.resolve() == v && isA(c.resolveMethod()?.containingClass, "java.lang.AutoCloseable")
    }
}

PsiElement prev = call
PsiElement parent = call.parent
while (true) {
    if (parent instanceof PsiParenthesizedExpression) { prev = parent; parent = parent.parent; continue }
    if (parent instanceof PsiReturnStatement) {
        def enclosing = PsiTreeUtil.getParentOfType(parent, PsiMethod, PsiLambdaExpression)
        return enclosing instanceof PsiLambdaExpression ? !lambdaOk(enclosing) : !isMbc(enclosing)
    }
    if (parent instanceof PsiLambdaExpression) return !lambdaOk(parent)
    if (parent instanceof PsiConditionalExpression && prev != parent.condition) { prev = parent; parent = parent.parent; continue }
    if (parent instanceof PsiReferenceExpression && parent.qualifierExpression == prev && parent.parent instanceof PsiMethodCallExpression) {
        // Like Error Prone (which compares erasures), any Stream method returning a Stream (map, filter, ...) passes the obligation along
        def next = parent.parent
        def m = next.resolveMethod()
        def ret = m?.returnType
        if (m != null && isA(m.containingClass, "java.util.stream.Stream") && ret instanceof PsiClassType && ret.rawType().canonicalText == "java.util.stream.Stream") { prev = next; parent = next.parent; continue }
        return true
    }
    if (parent instanceof PsiExpressionList && parent.parent instanceof PsiNewExpression) {
        def nc = parent.parent
        def ctor = nc.resolveConstructor()
        def args = parent.expressions
        if (ctor != null && args.length > 0 && args[0] == prev && ctor.throwsList.referencedTypes.length == 0 && ctor.parameterList.parametersCount > 0) {
            def decos = DECORATORS[ctor.parameterList.parameters[0].type.canonicalText]
            if (decos != null && decos.any { isA(ctor.containingClass, it) }) {
                if (isMbc(ctor)) return false
                prev = nc; parent = nc.parent; continue
            }
        }
        return true
    }
    if (parent instanceof PsiResourceVariable) return false
    if (parent instanceof PsiLocalVariable) return !closedInFinally(parent)
    if (parent instanceof PsiField && parent.hasModifierProperty(PsiModifier.STATIC) && parent.hasModifierProperty(PsiModifier.FINAL)) return false
    return true
}"

