"import com.intellij.psi.*
import com.intellij.psi.util.PsiUtil
import com.intellij.codeInsight.AnnotationUtil

def CTC = "com.google.errorprone.annotations.CompileTimeConstant"
def ok
ok = { PsiExpression e ->
    e = PsiUtil.skipParenthesizedExprDown(e)
    if (e == null || PsiUtil.isConstantExpression(e)) return true
    if (e instanceof PsiLiteralExpression && e.text == "null") return true
    if (e instanceof PsiReferenceExpression) {
        def target = e.resolve()
        return target instanceof PsiParameter && AnnotationUtil.isAnnotated(target, CTC, 0)
    }
    if (e instanceof PsiConditionalExpression) return ok(e.thenExpression) && ok(e.elseExpression)
    if (e instanceof PsiPolyadicExpression && e.operationTokenType == JavaTokenType.PLUS) return e.operands.every { ok(it) }
    return false
}

def call = __context__
if (!(call instanceof PsiCallExpression)) return false
def method = call.resolveMethod()
def args = call.argumentList?.expressions
if (method == null || args == null) return false
def params = method.parameterList.parameters
for (int i = 0; i < params.length; i++) {
    if (!AnnotationUtil.isAnnotated(params[i], CTC, 0)) continue
    int end = params[i].isVarArgs() ? args.length : Math.min(i + 1, args.length)
    for (int j = i; j < end; j++) {
        if (!ok(args[j])) return true
    }
}
return false"

"import com.intellij.psi.*
